using OpenAI;
using OpenAI.Chat;
using System.ClientModel;

public class LocalOllamaService
{
    private readonly ChatClient _chatClient;

    public LocalOllamaService()
    {
        // Point to Ollama's local OpenAI-compatible endpoint
        var clientOptions = new OpenAIClientOptions
        {
            Endpoint = new Uri("http://localhost:11434/v1")
        };

        // Dummy API key is accepted by local Ollama server
        var openAiClient = new OpenAIClient(new ApiKeyCredential("ollama"), clientOptions);
        _chatClient = openAiClient.GetChatClient("llama3.2");
    }

    public async Task<string> AskLocalModelAsync(string prompt, CancellationToken ct = default)
    {
        var messages = new List<ChatMessage>
        {
            new SystemChatMessage("You are a local developer assistant running completely on-premises."),
            new UserChatMessage(prompt)
        };

        var result = await _chatClient.CompleteChatAsync(messages, cancellationToken: ct);
        return result.Value.Content[0].Text;
    }
}
